import { existsSync, readFileSync } from "node:fs";
import { resolve } from "node:path";
import react from '@vitejs/plugin-react'
import { defineConfig } from 'vite'

// Serve on the LAN so a phone can reach Jarvis, and automatically
// switch to HTTPS when dev certificates exist (generated by
// scripts/make_dev_cert.py) — required for microphone access on
// Android, which only works in secure contexts.
//
// All /api traffic (including WebSocket) is proxied to the backend,
// so the browser only ever talks to this one origin: no CORS
// preflights on the phone and no second certificate to trust.
const certDir = resolve(import.meta.dirname, "../../data/certs");
// JARVIS_NO_HTTPS=1 forces plain HTTP (e.g. for automated UI tests).
const useHttps =
  process.env.JARVIS_NO_HTTPS !== "1" &&
  existsSync(resolve(certDir, "dev.crt")) &&
  existsSync(resolve(certDir, "dev.key"));

export default defineConfig({
  plugins: [react()],
  server: {
    host: true,
    proxy: {
      "/api": {
        target: "http://127.0.0.1:8000",
        changeOrigin: false,
        ws: true,
      },
    },
    ...(useHttps
      ? {
          https: {
            key: readFileSync(resolve(certDir, "dev.key")),
            cert: readFileSync(resolve(certDir, "dev.crt")),
          },
        }
      : {}),
  },
})
